-- -----------------------------------
-- Table structure for `sites_info`
-- -----------------------------------

DROP TABLE IF EXISTS `sites_info`;
CREATE TABLE `sites_info` (
  `id` int(6) NOT NULL AUTO_INCREMENT,
  `site_id` int(6) DEFAULT NULL,
  `atmid` varchar(40) CHARACTER SET utf8 DEFAULT NULL,
  `cam_ip` varchar(40) CHARACTER SET utf8 DEFAULT NULL,
  `port` varchar(40) CHARACTER SET utf8 DEFAULT NULL,
  `cam_name` varchar(40) CHARACTER SET utf8 DEFAULT NULL,
  `username` varchar(40) CHARACTER SET utf8 DEFAULT NULL,
  `password` varchar(40) CHARACTER SET utf8 DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `status` tinyint(1) DEFAULT NULL,
  `statusDate` datetime DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=MyISAM AUTO_INCREMENT=4736 DEFAULT CHARSET=latin1;

